-- | One input or output of a syscall.
data SyscallArg = SyscallArg
  { name :: String
    -- ^ The yaml name; C++ names the parameter input_<name> / output_<name>.
  , kind :: SyscallArgKind
  , typename :: Maybe String
    -- ^ The C++ type in syscalls.yaml; 'Nothing' for a span.
  }
  deriving (Eq, Show)

-- | @SyscallMeta<SyscallNo>@ plus the shape of @syscall_<Name>_inner@.
data SyscallMeta = SyscallMeta
  { syscallNo :: SyscallNo
    -- ^ kSyscallNo
  , name :: String
  , isReadOnly :: Bool
    -- ^ kIsReadOnlySyscall: callable from a read-only frame.
  , canReturn :: Bool
    -- ^ kCanReturn: false for syscalls that end the caller (Return, Exit).
  , needsContext :: Bool
    -- ^ The inner body takes the SystemCallHandler.
  , needsGas :: Bool
    -- ^ The inner body takes the frame's remaining gas (WrappedGasAmount).
  , isAsync :: Bool
    -- ^ The inner body returns MaybeAsyncSyscallInnerResult (may suspend).
  , inputs :: [SyscallArg]
    -- ^ kInputNames, with kinds.
  , outputs :: [SyscallArg]
    -- ^ kOutputNames, with kinds.
  , allowedErrors :: [SyscallErrorCode]
    -- ^ kAllowedErrors.
  }
  deriving (Eq, Show)

-- | @syscall_input_count@: argument slots after the syscall number.
kSyscallInputCount :: Int
kSyscallInputCount = 7

-- | Argument slots a syscall consumes (inputs, then outputs).
syscallArgSlots :: SyscallMeta -> Int
syscallArgSlots m =
  sum (map (\a -> kNumInputs a.kind) (m.inputs ++ m.outputs))

-- | 'syscallMeta' by name.
syscallMetaByName :: String -> Maybe SyscallMeta
syscallMetaByName n = case filter (\m -> m.name == n) syscallMetaTable of
  (m : _) -> Just m
  [] -> Nothing

-- | The entry for a syscall number, or 'Nothing' for an unknown number.
syscallMeta :: SyscallNo -> Maybe SyscallMeta
syscallMeta (SyscallNo n)
  | n < 0 || n >= (kSyscallCount :: Int32) = Nothing
  | otherwise = Just (syscallMetaTable !! fromIntegral n)

